<script>(function(){var agency=document.getElementById('opening-agency-name'),media=document.getElementById('opening-media'),operator=document.getElementById('opening-operator'),groups=@json($advertisingAgencyGroups),oldAgencyId=String(media.getAttribute('data-old-agency-id')||''),emailWrap=document.getElementById('opening-email-wrap'),profileWrap=document.getElementById('opening-profile-wrap'),bcidWrap=document.getElementById('opening-bcid-wrap'),email=document.getElementById('opening-email'),profile=document.getElementById('opening-profile'),bcid=document.getElementById('opening-bcid');function type(value){value=(value||'').toLowerCase().replace(/[\s_-]+/g,'');if(value.indexOf('facebook')>=0||value.indexOf('脸书')>=0)return'facebook';if(value.indexOf('tiktok')>=0||value.indexOf('抖音')>=0)return'tiktok';if(value.indexOf('google')>=0||value.indexOf('谷歌')>=0||value.indexOf('bigo')>=0||value.indexOf('mediago')>=0)return'email';return'other'}function toggle(){var current=type(media.options[media.selectedIndex]?media.options[media.selectedIndex].text:''),needsEmail=current==='facebook'||current==='email';emailWrap.style.display=needsEmail?'block':'none';profileWrap.style.display=current==='facebook'?'block':'none';bcidWrap.style.display=current==='tiktok'?'block':'none';email.required=needsEmail;profile.required=current==='facebook';bcid.required=current==='tiktok'}function fill(selected){var options=groups[agency.value]||[];media.innerHTML='<option value="">'+(options.length?'请选择社媒':'该代理暂无可用社媒')+'</option>';options.forEach(function(item){var option=document.createElement('option');option.value=item.key;option.textContent=item.media;if(String(item.key)===String(selected||''))option.selected=true;media.appendChild(option)});media.disabled=!options.length;toggle()}agency.addEventListener('change',function(){fill('')});media.addEventListener('change',toggle);if(oldAgencyId){Object.keys(groups).some(function(name){if((groups[name]||[]).some(function(item){return String(item.key)===oldAgencyId})){agency.value=name;fill(oldAgencyId);return true}return false})}else toggle();if(operator)operator.addEventListener('change',function(){location.href=this.dataset.url+'?operator_user_id='+encodeURIComponent(this.value)});})();</script>
